[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$TaskDirectory,[Parameter(Mandatory=$true)][string]$RequirementsJson)
$ErrorActionPreference='Stop'; Import-Module (Join-Path $PSScriptRoot 'PipelineProtocolV2.psm1') -Force
$value=Get-Content -Raw $RequirementsJson|ConvertFrom-Json;$items=@($value.requirements);if($items.Count -eq 0){throw 'requirements must not be empty'};$ids=@{};foreach($r in $items){if([string]::IsNullOrWhiteSpace([string]$r.id) -or [string]$r.id -notmatch '^(REQ|NEG)-'){throw 'requirement id must be stable REQ-/NEG-'};if($ids.ContainsKey($r.id)){throw "duplicate requirement id: $($r.id)"};$ids[$r.id]=$true;if(@($r.source_refs).Count -eq 0){throw "requirement $($r.id) needs source_refs"};if($r.status -notin @('active','accepted','rejected','open')){throw "invalid requirement status: $($r.id)"}};$dir=Join-Path $TaskDirectory 'requirements-revisions';[IO.Directory]::CreateDirectory($dir)|Out-Null;$id='REQREV-{0:D4}' -f ((Get-ChildItem $dir -Filter '*.json' -ErrorAction SilentlyContinue).Count+1);$file=Join-Path $dir "$id.json";Write-PipelineImmutableJson $file $value|Out-Null;$hash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();Write-AtomicJson (Join-Path $TaskDirectory 'requirements-current.json') ([ordered]@{revision_id=$id;path=$file;sha256=$hash});$value|ConvertTo-Json -Depth 30
